CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('engineer','reviewer','admin')),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id_hash TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),csrf_token TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),form_version TEXT NOT NULL CHECK(form_version IN('V1','V2','V3')),status TEXT NOT NULL CHECK(status IN('draft','submitted')),fields_json TEXT NOT NULL CHECK(json_valid(fields_json)),version INTEGER NOT NULL DEFAULT 1 CHECK(version>=1),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,source_json TEXT CHECK(source_json IS NULL OR json_valid(source_json)));
CREATE INDEX IF NOT EXISTS reports_owner_updated ON reports(owner_id,updated_at);
CREATE TABLE IF NOT EXISTS comments(id TEXT PRIMARY KEY,report_id TEXT NOT NULL REFERENCES reports(id),author_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 4000),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS systems(id TEXT PRIMARY KEY,identity TEXT UNIQUE NOT NULL,name TEXT NOT NULL,city TEXT NOT NULL DEFAULT '',hospital TEXT NOT NULL DEFAULT '',application_experts TEXT NOT NULL DEFAULT '',issues TEXT NOT NULL DEFAULT '',readiness TEXT NOT NULL DEFAULT 'unknown' CHECK(readiness IN('ready','not_ready','unknown')),source_json TEXT CHECK(source_json IS NULL OR json_valid(source_json)),version INTEGER NOT NULL DEFAULT 1 CHECK(version>=1),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_items(id TEXT PRIMARY KEY,system_id TEXT NOT NULL REFERENCES systems(id),category TEXT NOT NULL CHECK(category IN('Hardware','Cranial instruments','Spine instruments','Other components')),name TEXT NOT NULL,serial_number TEXT,quantity INTEGER CHECK(quantity IS NULL OR (quantity>=0 AND typeof(quantity)='integer')),availability TEXT NOT NULL CHECK(availability IN('available','unavailable','unknown')),remarks TEXT NOT NULL DEFAULT '',source_json TEXT CHECK(source_json IS NULL OR json_valid(source_json)),version INTEGER NOT NULL DEFAULT 1 CHECK(version>=1),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_movements(id TEXT PRIMARY KEY,system_id TEXT NOT NULL REFERENCES systems(id),item_name TEXT NOT NULL,event_date TEXT,quantity INTEGER CHECK(quantity IS NULL OR (quantity>=0 AND typeof(quantity)='integer')),provided_by TEXT NOT NULL DEFAULT '',reference_note TEXT NOT NULL DEFAULT '',cost REAL CHECK(cost IS NULL OR cost>=0),created_at TEXT NOT NULL,source_json TEXT CHECK(source_json IS NULL OR json_valid(source_json)));
CREATE TABLE IF NOT EXISTS import_batches(id TEXT PRIMARY KEY,workbook_hash TEXT NOT NULL,filename TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,report_count INTEGER NOT NULL,inventory_count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS imported_rows(fingerprint TEXT PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES import_batches(id),entity_type TEXT NOT NULL,entity_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,changed_fields_json TEXT NOT NULL CHECK(json_valid(changed_fields_json)),created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS inventory_system ON inventory_items(system_id);
CREATE INDEX IF NOT EXISTS comments_report ON comments(report_id,created_at);
CREATE INDEX IF NOT EXISTS audit_created ON audit_events(created_at);
